// Emits one item per configured asset. Adding an asset = ONE array entry
// here; node count and wiring never change (that is the point of this shape).
//
// ASSET_ALLOWLIST and isAllowedAsset no longer exist in src/market/assets.ts
// (removed by the dynamic-asset-count change). /api/cycle now validates each
// symbol by format only (isWellFormedAsset, pattern ^[A-Z0-9]{2,20}USDT$),
// independent of any list, plus a standalone MAX_ASSETS=25 cap. Adding or
// removing a symbol here needs no app-side change beyond staying within
// that cap (openspec/changes/dynamic-asset-count/proposal.md).
//
// 24 symbols, ordered by general market relevance (market cap/liquidity) --
// well below the MAX_ASSETS=25 ceiling.
const SYMBOLS = [
  'BTCUSDT',
  'ETHUSDT',
  'XRPUSDT',
  'BNBUSDT',
  'SOLUSDT',
  'DOGEUSDT',
  'TRXUSDT',
  'ADAUSDT',
  'AVAXUSDT',
  'LINKUSDT',
  'TONUSDT',
  'SHIBUSDT',
  'SUIUSDT',
  'DOTUSDT',
  'LTCUSDT',
  'BCHUSDT',
  'NEARUSDT',
  'UNIUSDT',
  'APTUSDT',
  'ICPUSDT',
  'ETCUSDT',
  'XLMUSDT',
  'ATOMUSDT',
  'FILUSDT'
];

// pairedItem is stated explicitly: every symbol item derives from the single
// Schedule Trigger item. This keeps n8n's item-linking chain complete for the
// downstream $('Symbols').item back-reference in 'Set Symbol'.
return SYMBOLS.map((symbol) => ({ json: { symbol }, pairedItem: { item: 0 } }));

// Each incoming item carries one asset's symbol + raw Binance klines
// response (array of [openTime, open, high, low, close, volume, closeTime, ...]),
// both attached explicitly by the per-branch 'Set Symbol - {SYMBOL}' node
// upstream. No positional (item-order) inference is used here.

function toCandle(row) {
  return {
    openTime: Number(row[0]),
    open: Number(row[1]),
    high: Number(row[2]),
    low: Number(row[3]),
    close: Number(row[4]),
    volume: Number(row[5]),
  };
}

const assets = items.map((item) => ({
  symbol: item.json.symbol,
  klines: item.json.klines.map(toCandle),
}));

return [{ json: { market: 'crypto', assets } }];

// Emits one item per configured US equity ticker. Mirrors 'Symbols' (the
// crypto branch's equivalent node): one array entry per asset, node count
// and wiring never change. Adding a ticker = one array entry here.
//
// /api/cycle validates each symbol via ACCIONES_SYMBOL_PATTERN
// (^[A-Z]{1,5}(\.[A-Z])?$ - src/market/assets.ts), independent of any
// list, plus the shared MAX_ASSETS=25 cap applied per market
// (openspec/changes/acciones-market-integration/design.md D-C).
//
// 24 symbols, large-cap US equities across sectors -- well below the
// MAX_ASSETS=25 ceiling.
const SYMBOLS = [
  'AAPL',
  'MSFT',
  'GOOGL',
  'AMZN',
  'NVDA',
  'META',
  'TSLA',
  'BRK.B',
  'JPM',
  'V',
  'UNH',
  'XOM',
  'JNJ',
  'WMT',
  'PG',
  'MA',
  'HD',
  'CVX',
  'MRK',
  'ABBV',
  'KO',
  'PEP',
  'AVGO',
  'COST'
];

// pairedItem is stated explicitly: every symbol item derives from the
// single Schedule Trigger item. This keeps n8n's item-linking chain
// complete for the downstream $('Acciones Symbols').item back-reference in
// 'Set Acciones Symbol'.
return SYMBOLS.map((symbol) => ({ json: { symbol }, pairedItem: { item: 0 } }));

// Each incoming item carries one ticker's symbol + raw Twelve Data values
// array (strings: {datetime, open, high, low, close, volume, ...}), both
// attached explicitly by 'Set Acciones Symbol' upstream. No positional
// (item-order) inference is used here.
//
// No explicit re-sort: src/stream/window.ts already sorts candles by
// openTime before building the candle window, so Twelve Data's
// most-recent-first ordering needs no correction here (closes
// acciones-market-integration design.md Open Question 3).

function toCandle(row) {
  return {
    openTime: Date.parse(row.datetime),
    open: Number(row.open),
    high: Number(row.high),
    low: Number(row.low),
    close: Number(row.close),
    volume: Number(row.volume),
  };
}

const assets = items.map((item) => ({
  symbol: item.json.symbol,
  klines: item.json.klines.map(toCandle),
}));

return [{ json: { market: 'acciones', assets } }];
